sp_widget.client_script:
api.controller = function ($scope, $element, $http, $q, $filter) {

    var c = this;

    // =========================================================
    // STEP CONFIGURATION
    // =========================================================

    c.titles = [
        'Vehicle information',
        'Owner details',
        'Warranty selection',
        'Documents',
        'Review and submit'
    ];

    c.subs = [
        'Vehicle and purchase details',
        'Owner and contact information',
        'Choose your warranty plan',
        'Upload the required documents',
        'Review everything before submitting'
    ];

    c.icons = [
        'fa-car',
        'fa-user',
        'fa-shield',
        'fa-upload',
        'fa-check-square-o'
    ];

    c.idTypes = [
        "Driver's License",
        "State ID Card",
        "Passport",
        "Military ID"
    ];

    c.docs = [
        {
            key: 'invoice',
            label: 'Purchase invoice'
        },
        {
            key: 'rc',
            label: 'Vehicle registration certificate (RC)'
        },
        {
            key: 'idproof',
            label: 'Owner ID proof'
        }
    ];


    // =========================================================
    // INITIAL STATE
    // =========================================================

    c.cur = 1;
    c.err = '';
    c.done = false;
    c.busy = false;
    c.files = {};

    c.v = c.data.v || {};
    c.data.plans = c.data.plans || [];

    var o = c.data.o || {};


    // =========================================================
    // FORM DATA
    // =========================================================

    c.f = {

        delivery: c.data.today
            ? new Date(c.data.today + 'T00:00:00')
            : null,

        regNo: '',
        invoice: '',

        colour: c.v.colour || '',
        odometer: c.v.odometer || 0,

        name: o.name || '',
        mobile: o.mobile || '',
        email: o.email || '',

        idType: '',
        idNo: '',

        street: o.street || '',
        city: o.city || '',
        state: o.state || '',
        pin: o.pin || '',
        country: o.country || 'India',

        plan: c.data.plans.length
            ? c.data.plans[0].id
            : '',

        terms: false
    };


    // =========================================================
    // SELECTED WARRANTY PLAN
    // =========================================================

    c.sel = function () {

        for (var i = 0; i < c.data.plans.length; i++) {

            if (c.data.plans[i].id == c.f.plan) {
                return c.data.plans[i];
            }

        }

        return {
            id: '',
            name: '',
            term: 0,
            price: 0,
            km: 0
        };
    };


    // =========================================================
    // WARRANTY END DATE
    // =========================================================

    c.endDate = function (months) {

        if (!c.f.delivery) {
            return null;
        }

        var date = new Date(c.f.delivery);

        date.setMonth(
            date.getMonth() + (parseInt(months, 10) || 0)
        );

        date.setDate(
            date.getDate() - 1
        );

        return date;
    };


    // =========================================================
    // VALIDATION
    // =========================================================

    function validate(step) {

        c.err = '';

        // STEP 1
        if (step == 1) {

            if (!c.v.inv) {
                return 'No vehicle is selected.';
            }

            if (!c.v.vin) {
                return 'VIN is missing from the selected Inventory record.';
            }

            if (!c.f.regNo) {
                return 'Enter the registration number.';
            }

            if (!c.f.delivery) {
                return 'Enter the purchase date.';
            }

            if (!c.f.invoice) {
                return 'Enter the invoice number.';
            }
        }


        // STEP 2
        if (step == 2) {

            if (!c.f.mobile) {
                return 'Enter the mobile number.';
            }

            if (!c.f.email) {
                return 'Enter the email address.';
            }

            if (!c.f.idType) {
                return 'Select the ID type.';
            }

            if (!c.f.idNo) {
                return 'Enter the ID number.';
            }

            if (!c.f.street) {
                return 'Enter the street address.';
            }

            if (!c.f.city) {
                return 'Enter the city.';
            }

            if (!c.f.state) {
                return 'Enter the state.';
            }

            if (!c.f.pin) {
                return 'Enter the PIN code.';
            }
        }


        // STEP 3
        if (step == 3) {

            if (!c.data.plans.length) {
                return 'No eligible warranty plans are available for this vehicle.';
            }

            if (!c.f.plan) {
                return 'Select a warranty plan.';
            }
        }


        // STEP 4
        if (step == 4) {

            if (!c.files.invoice) {
                return 'Upload the purchase invoice.';
            }

            if (!c.files.rc) {
                return 'Upload the vehicle registration certificate (RC).';
            }

            if (!c.files.idproof) {
                return 'Upload the owner ID proof.';
            }
        }


        // STEP 5
        if (step == 5) {

            if (!c.f.terms) {
                return 'Accept the warranty terms and conditions.';
            }
        }


        return '';
    }


    // =========================================================
    // NAVIGATION
    // =========================================================

    c.go = function (target) {

        target = parseInt(target, 10);

        if (!target || target < 1 || target > 5) {
            return;
        }

        // Already on the selected step
        if (target == c.cur) {
            c.err = '';
            return;
        }


        // Going backward is always allowed
        if (target < c.cur) {
            c.err = '';
            c.cur = target;
            return;
        }


        // Going forward:
        // every previous step must be valid first.
        for (var step = c.cur; step < target; step++) {

            var error = validate(step);

            if (error) {
                c.err = error;
                c.cur = step;
                return;
            }
        }


        c.err = '';
        c.cur = target;
    };


    // =========================================================
    // NEXT
    // =========================================================

    c.next = function () {

        if (c.cur >= 5) {
            return;
        }

        var error = validate(c.cur);

        if (error) {
            c.err = error;
            return;
        }

        c.err = '';
        c.cur++;
    };


    // =========================================================
    // BACK
    // =========================================================

    c.back = function () {

        if (c.cur <= 1) {
            return;
        }

        c.err = '';
        c.cur--;
    };


    // =========================================================
    // FILE UPLOAD / SELECTION
    // =========================================================

    $element.on(
        'change',
        'input[type=file]',
        function (event) {

            var key = this.getAttribute('data-key');
            var file = event.target.files[0];

            $scope.$apply(function () {

                if (!file) {
                    return;
                }

                // Maximum 5 MB
                if (file.size > 5 * 1024 * 1024) {

                    c.err = 'The file is larger than 5 MB.';
                    return;
                }

                // Supported formats
                var allowed = [
                    'application/pdf',
                    'image/jpeg',
                    'image/png'
                ];

                if (
                    file.type &&
                    allowed.indexOf(file.type) === -1
                ) {

                    c.err =
                        'Only PDF, JPG and PNG files are allowed.';

                    return;
                }

                c.err = '';
                c.files[key] = file;
            });

        }
    );


    // =========================================================
    // ATTACHMENT UPLOAD
    // =========================================================

    function upload(file, sysId) {

        return $http.post(
            '/api/now/attachment/file' +
            '?table_name=u_warranty_registration' +
            '&table_sys_id=' + sysId +
            '&file_name=' + encodeURIComponent(file.name),
            file,
            {
                headers: {
                    'Content-Type':
                        file.type ||
                        'application/octet-stream'
                },

                transformRequest:
                    angular.identity
            }
        );
    }


    // =========================================================
    // SUBMIT
    // =========================================================

    c.submit = function () {

        var error = validate(5);

        if (error) {
            c.err = error;
            return;
        }

        c.err = '';
        c.busy = true;


        var formData = angular.copy(c.f);

        formData.delivery =
            $filter('date')(
                c.f.delivery,
                'yyyy-MM-dd'
            ) || '';

        formData.inv = c.v.inv;


        // Tell Server Script to submit
        c.data.action = 'submit';
        c.data.form = formData;


        c.server.update().then(function () {

            c.data.action = undefined;


            // Server-side failure
            if (
                c.data.error ||
                !c.data.newId
            ) {

                c.err =
                    c.data.error ||
                    'Submission failed.';

                c.busy = false;
                return;
            }


            // Upload all three documents
            $q.all(
                c.docs.map(function (doc) {

                    return upload(
                        c.files[doc.key],
                        c.data.newId
                    );

                })
            )
            .then(function () {

                c.ref = c.data.ref;

                c.valid =
                    c.endDate(
                        c.data.stdMonths +
                        c.sel().term
                    );

                c.done = true;
                c.busy = false;

            })
            .catch(function () {

                c.err =
                    'The registration was created (' +
                    c.data.ref +
                    '), but one or more attachments could not be uploaded.';

                c.busy = false;
            });


        }, function () {

            c.err =
                'No response from the server. Please try again.';

            c.busy = false;

        });

    };

};

sp_widget.css:
.sn-chrome{
  background:#fff;
  border:1px solid #c8d5e3;
  border-radius:12px;
  overflow:hidden;
  font-size:13px;
}

.sn-header{
  background:#1a3d66;
  padding:10px 16px;
  display:flex;
  align-items:center;
  justify-content:space-between;
}

.sn-logo{
  color:#fff;
  font-size:14px;
  font-weight:500;
  display:flex;
  align-items:center;
  gap:8px;
}

.sn-logo i{
  color:#72b8f5;
  font-size:18px;
}

.sn-nav{
  display:flex;
  align-items:center;
  gap:14px;
}

.sn-nav a{
  color:#aacfee;
  font-size:12px;
  text-decoration:none;
}

.sn-nav i{
  color:#aacfee;
}

.sn-avatar{
  width:28px;
  height:28px;
  border-radius:50%;
  background:#2d6a9f;
  display:flex;
  align-items:center;
  justify-content:center;
  color:#fff;
  font-size:11px;
}

.sn-breadcrumb{
  background:#f0f4f8;
  border-bottom:1px solid #c8d5e3;
  padding:8px 16px;
  font-size:12px;
  color:#5a7a96;
  display:flex;
  align-items:center;
  gap:6px;
}

.sn-breadcrumb b{
  color:#1a3d66;
  font-weight:500;
}

.sn-ref{
  margin-left:auto;
  background:#1a3d66;
  color:#fff;
  font-size:11px;
  font-weight:500;
  padding:3px 8px;
  border-radius:3px;
}

.sn-body{
  display:grid;
  grid-template-columns:220px 1fr;
  min-height:500px;
}

.sn-sidebar{
  background:#f7f9fb;
  border-right:1px solid #c8d5e3;
  padding:16px 0;
}

.sn-sidebar-title{
  font-size:11px;
  font-weight:500;
  color:#5a7a96;
  text-transform:uppercase;
  letter-spacing:.07em;
  padding:0 16px 8px;
}

.sn-sidebar-item{
  padding:8px 16px;
  cursor:pointer;
  font-size:13px;
  color:#2d4a63;
  display:flex;
  align-items:center;
  gap:8px;
  border-left:3px solid transparent;
}

.sn-sidebar-item.active{
  background:#e6f0f8;
  border-left-color:#1a3d66;
  color:#1a3d66;
  font-weight:500;
}

.sn-sidebar-item i{
  width:18px;
  color:#5a7a96;
}

.sn-sidebar-item.active i{
  color:#1a3d66;
}

.sn-sidebar-item.done,
.sn-sidebar-item.done i{
  color:#27a060;
}

.sidebar-help{
  margin:20px 16px 8px;
  border-top:1px solid #c8d5e3;
  padding-top:16px;
}

.help-title{
  font-size:11px;
  color:#5a7a96;
  margin-bottom:8px;
  font-weight:500;
  text-transform:uppercase;
  letter-spacing:.06em;
}

.help-item{
  color:#2d6a9f;
  display:flex;
  align-items:center;
  gap:6px;
  font-size:12px;
  margin-bottom:8px;
}

.sn-right{
  min-width:0;
  display:flex;
  flex-direction:column;
}

.sn-main{
  padding:24px 28px;
  background:#fff;
  flex:1;
}

.sn-form-header{
  margin-bottom:20px;
}

.sn-form-heading{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
}

.sn-form-title{
  font-size:18px;
  font-weight:500;
  color:#1a3d66;
  margin-bottom:4px;
}

.sn-form-sub{
  font-size:13px;
  color:#5a7a96;
}

.sn-progress{
  font-size:12px;
  color:#5a7a96;
}

.step-indicator{
  display:flex;
  align-items:center;
  gap:6px;
  margin-top:10px;
  margin-bottom:16px;
}

.step-dot{
  width:8px;
  height:8px;
  border-radius:50%;
  background:#c8d5e3;
}

.step-dot.done{
  background:#27a060;
}

.step-dot.active{
  background:#1a3d66;
  width:24px;
  border-radius:4px;
}

.sn-section{
  background:#fff;
  border:1px solid #c8d5e3;
  border-radius:6px;
  margin-bottom:16px;
  overflow:hidden;
}

.sn-section-head{
  background:#e8eff7;
  border-bottom:1px solid #c8d5e3;
  padding:10px 16px;
  display:flex;
  align-items:center;
  gap:8px;
}

.sn-section-head i{
  color:#1a3d66;
  font-size:16px;
}

.sn-section-head span{
  font-size:13px;
  font-weight:500;
  color:#1a3d66;
}

.sn-section-body{
  padding:16px;
}

.sn-field-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:12px 20px;
}

.sn-field-grid.cols3{
  grid-template-columns:1fr 1fr 1fr;
}

.sn-field{
  display:flex;
  flex-direction:column;
  gap:5px;
}

.sn-field label,
.sn-doc-field label{
  font-size:12px;
  font-weight:500;
  color:#3d5a74;
}

.req{
  color:#c0392b;
  margin-left:2px;
}

.sn-input,
.sn-select{
  width:100%;
  padding:7px 10px;
  font-size:13px;
  border:1px solid #a8bdd1;
  border-radius:4px;
  background:#fff;
  color:#1a2d3d;
  outline:none;
}

.sn-input:focus,
.sn-select:focus{
  border-color:#1a3d66;
  box-shadow:0 0 0 2px rgba(26,61,102,.12);
}

.sn-readonly{
  background:#f5f7fa;
  color:#5a7a96;
}

.info-banner,
.info-warning{
  border-radius:4px;
  padding:10px 14px;
  margin-bottom:16px;
  display:flex;
  align-items:flex-start;
  gap:10px;
}

.info-banner{
  background:#e6f0f8;
  border:1px solid #a8c4dc;
}

.info-warning{
  background:#fff8d9;
  border:1px solid #e9d978;
  color:#6a5b00;
}

.info-banner i{
  color:#1a3d66;
  margin-top:1px;
}

.info-warning i{
  color:#9a8500;
  margin-top:1px;
}

.info-banner p,
.info-warning span{
  margin:0;
  font-size:12px;
  line-height:1.6;
}

.warranty-card{
  border:1px solid #c8d5e3;
  border-radius:6px;
  padding:12px 14px;
  margin-bottom:10px;
  cursor:pointer;
  display:flex;
  align-items:flex-start;
  gap:12px;
  transition:.15s;
}

.warranty-card:hover{
  border-color:#1a3d66;
}

.warranty-card.selected{
  border-color:#1a3d66;
  background:#e6f0f8;
}

.warranty-card input{
  margin-top:2px;
  accent-color:#1a3d66;
}

.wc-info{
  flex:1;
}

.wc-name{
  font-size:13px;
  font-weight:500;
  color:#1a3d66;
  margin-bottom:3px;
}

.wc-desc{
  font-size:12px;
  color:#5a7a96;
  margin-bottom:5px;
}

.wc-meta{
  color:#2d4a63;
  font-size:12px;
}

.wc-badge{
  display:inline-block;
  background:#dff0d8;
  color:#2e6b3c;
  font-size:11px;
  font-weight:500;
  padding:2px 8px;
  border-radius:3px;
  margin-top:5px;
}

.wc-price{
  font-size:14px;
  font-weight:500;
  color:#1a3d66;
  margin-left:auto;
  white-space:nowrap;
}

.sn-doc-field{
  display:flex;
  flex-direction:column;
  gap:6px;
  margin-bottom:14px;
}

.upload-area{
  position:relative;
  border:1.5px dashed #a8bdd1;
  border-radius:6px;
  padding:20px;
  text-align:center;
  background:#f7f9fb;
  overflow:hidden;
}

.upload-area i{
  display:block;
  font-size:28px;
  color:#a8bdd1;
  margin-bottom:8px;
}

.upload-area > div{
  font-size:12px;
  color:#5a7a96;
}

.upload-area small{
  display:block;
  margin-top:4px;
  color:#5a7a96;
}

.upload-link{
  color:#1a3d66;
  font-weight:500;
  text-decoration:underline;
}

.upload-input{
  position:absolute;
  inset:0;
  opacity:0;
  cursor:pointer;
}

.uploaded-file{
  display:flex;
  align-items:center;
  gap:10px;
  padding:8px 12px;
  background:#f7f9fb;
  border:1px solid #c8d5e3;
  border-radius:4px;
  margin-top:8px;
}

.uploaded-file i{
  color:#1a3d66;
}

.uploaded-file span{
  flex:1;
  font-size:12px;
  color:#2d4a63;
}

.upload-ok{
  color:#27a060 !important;
}

.edit-link{
  margin-left:auto;
  font-size:12px;
  color:#2d6a9f;
  cursor:pointer;
  text-decoration:none;
}

.terms-box{
  background:#f0f7ee;
  border:1px solid #a3d4b5;
  border-radius:6px;
  padding:12px 16px;
  display:flex;
  align-items:flex-start;
  gap:10px;
}

.terms-box label{
  font-size:12px;
  color:#2d4a63;
  line-height:1.6;
}

.sn-footer{
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding:14px 28px;
  border-top:1px solid #c8d5e3;
  background:#f0f4f8;
}

.footer-actions{
  display:flex;
  align-items:center;
  gap:10px;
}

.sn-btn{
  padding:8px 18px;
  border-radius:4px;
  font-size:13px;
  font-weight:500;
  cursor:pointer;
  border:none;
}

.sn-btn-primary{
  background:#1a3d66;
  color:#fff;
}

.sn-btn-secondary{
  background:#fff;
  color:#1a3d66;
  border:1px solid #a8bdd1;
}

.sn-btn-success{
  background:#27a060;
  color:#fff;
}

.sn-empty{
  background:#fff;
  border:1px solid #c8d5e3;
  border-radius:12px;
  padding:48px;
  text-align:center;
  color:#5a7a96;
}

.sn-empty i{
  font-size:48px;
  color:#a8bdd1;
  margin-bottom:12px;
}

.success{
  padding:48px;
  text-align:center;
}

.success-icon{
  font-size:56px;
  color:#27a060;
  margin-bottom:12px;
}

.success-reference{
  display:inline-block;
  background:#f0f4f8;
  border:1px solid #c8d5e3;
  border-radius:6px;
  padding:14px 20px;
  margin:20px 0;
}

.success-reference small{
  display:block;
  font-size:11px;
  color:#5a7a96;
}

.success-reference div{
  font-size:18px;
  font-weight:500;
  color:#1a3d66;
}

.success-summary{
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  gap:12px 36px;
  margin-bottom:24px;
}

.success-summary small{
  display:block;
  font-size:11px;
  color:#5a7a96;
  text-transform:uppercase;
}

.success-summary b{
  color:#1a3d66;
}

@media(max-width:768px){

  .sn-body{
    grid-template-columns:1fr;
  }

  .sn-sidebar{
    border-right:none;
    border-bottom:1px solid #c8d5e3;
  }

  .sn-field-grid,
  .sn-field-grid.cols3{
    grid-template-columns:1fr;
  }

  .sn-nav{
    display:none;
  }

  .sn-main{
    padding:18px;
  }

  .sn-footer{
    padding:12px 18px;
  }

}

sp_widget.script:
(function () {
  // ===== CONFIG =====
  var T = {inv: 'u_inventory', cust: 'u_customer_details', plan: 'u_warranty_plan', reg: 'u_warranty_registration'};
  var STD_MONTHS = 24;               // standard manufacturer warranty (months)
  var TERM_IS_TOTAL = true;          // plan "Term (Months)" holds TOTAL months (24/36/48/60)
  var CUR = '$';                     // currency symbol shown on plan cards ('$' or '₹')

  function num(v) { return parseFloat(String(v || '0').replace(/[^0-9.]/g, '')) || 0; }
  function ext(v) {                  // extra months = total term - standard warranty
    var t = parseInt(String(v || '0').replace(/[^0-9]/g, ''), 10) || 0;
    return TERM_IS_TOTAL ? Math.max(t - STD_MONTHS, 0) : t;
  }
  function list(v) {                 // "Tesla, Ford,BMW" -> ['tesla','ford','bmw']
    return String(v || '').split(',').map(function (s) { return s.trim().toLowerCase(); })
                          .filter(function (s) { return s; });
  }
  // Returns the value of the first field in the list that exists and is not empty (no error if a field is missing)
  function pick(gr, names) {
    for (var i = 0; i < names.length; i++)
      if (gr.isValidField(names[i]) && gr.getValue(names[i])) return String(gr.getValue(names[i]));
    return '';
  }

  data.today = new GlideDate().getValue();   // yyyy-MM-dd
  data.stdMonths = STD_MONTHS;
  data.cur = CUR;
  data.v = {}; data.o = {};

  // 1) Inventory + Customer (URL: ?id=warranty_reg&inv=<sys_id>; on submit it is also read from the form)
  var invId = $sp.getParameter('inv') || (input && input.form && input.form.inv) || '';
  var inv = new GlideRecord(T.inv);
  if (invId && inv.get(invId)) {
    data.v = {
      inv: invId,
      vin: pick(inv, ['u_vin']),
      mmt: pick(inv, ['u_make_model_trim']),
      year: pick(inv, ['u_model_year']),
      odometer: parseInt(pick(inv, ['u_odometer_reading']), 10) || 0,
      colour: pick(inv, ['u_exterior_interior_color', 'u_exterior_color', 'u_colour']).substring(0, 40),
      dealer: inv.isValidField('u_dealer_name') ? inv.getDisplayValue('u_dealer_name') : ''
    };
    var cid = inv.getValue('u_customer');           // the Customer reference lives on Inventory
    var c = new GlideRecord(T.cust);
    if (cid && c.get(cid)) {
      var a1 = pick(c, ['u_address_line_1']), st = pick(c, ['u_street']);
      data.o = {
        customer: c.getUniqueValue(),
        name: pick(c, ['u_name']),
        mobile: pick(c, ['u_number', 'u_mobile', 'u_phone']),
        email: pick(c, ['u_email']),
        street: (a1 && st && a1 != st ? a1 + ', ' + st : (a1 || st)).substring(0, 100),
        city: pick(c, ['u_city']), state: pick(c, ['u_state']),
        pin: pick(c, ['u_zip_code']), country: pick(c, ['u_country']) || 'India'
      };
    }
  }

  // 2) Plans: active + within date range + matching the vehicle's Make and Model Year
  var vMmt = String(data.v.mmt || '').trim().toLowerCase();
  var vYear = String(data.v.year || '').replace(/[^0-9]/g, '');
  data.plans = [];
  var p = new GlideRecord(T.plan);
  var qc = p.addQuery('u_status', 'active');
  qc.addOrCondition('u_status', 'Active');
  p.query();
  while (p.next()) {
    var eff = p.getValue('u_effective_date'), exp = p.getValue('u_expiration_date');
    if (eff && eff > data.today) continue;          // not effective yet
    if (exp && exp < data.today) continue;          // already expired
    var makes = list(p.getValue('u_applicable_makes'));
    var years = list(p.getValue('u_applicable_model_years'));
    if (makes.length && vMmt) {                     // one of the plan's makes must appear in "Make / Model / Trim"
      var okMake = makes.some(function (m) { return vMmt.indexOf(m) > -1; });
      if (!okMake) continue;
    }
    if (years.length && vYear && years.indexOf(vYear) < 0) continue;   // empty = all years
   data.plans.push({
    id: p.getUniqueValue(),

    // Warranty Plan master data
    name: p.getValue('u_plan_name'),
    desc: p.getValue('u_description'),

    // Price
    price: num(p.getValue('u_price')),

    // Extra months beyond standard manufacturer warranty
    term: ext(p.getValue('u_term_months')),

    // Actual Warranty Registration values
    totalTerm: parseInt(
        p.getValue('u_term_months'),
        10
    ) || 0,

    coverageMileage: num(
        p.getValue('u_coverage_mileage_limit')
    ),

    deductible: num(
        p.getValue('u_deductible_amount')
    ),

    // Plan category
    category: p.getValue('u_plan_category')
});
  }
  data.plans.sort(function (a, b) { return a.price - b.price; });

  // 3) Submit -> creates a single Warranty Registration record
  if (input && input.action == 'submit') {
    var f = input.form || {}, pl = new GlideRecord(T.plan);
    if (!f.inv || !data.v.inv) { data.error = 'No vehicle selected. Open this page from the Inventory record using the Warranty Registration button.'; return; }
    if (!data.o.customer) { data.error = 'No customer is set on this Inventory record.'; return; }
    if (!f.plan || !pl.get(f.plan)) { data.error = 'Please select a warranty plan.'; return; }

    var gdt = new GlideDateTime(f.delivery + ' 00:00:00');
    gdt.addMonthsUTC(STD_MONTHS + ext(pl.getValue('u_term_months'))); gdt.addDaysUTC(-1);

    var r = new GlideRecord(T.reg);
    r.initialize();                                  // applies the default for Number (auto number)
    r.setValue('u_vin', f.inv);
    r.setValue('u_customer', data.o.customer);
    r.setValue('u_warranty_plan', f.plan);
    r.setValue('u_delivery_date', f.delivery);
    r.setValue('u_warranty_start_date', f.delivery);
    r.setValue('u_warranty_end_date', gdt.getDate().getValue());
    r.setValue('u_odometer_at_registeration', parseInt(f.odometer, 10) || 0);
    // Warranty Type = plan category (powertrain / bumper_to_bumper / extended_care / standard)
    r.setValue('u_warranty_type', String(pl.getValue('u_plan_category') || 'standard').toLowerCase().replace(/[^a-z0-9]+/g, '_'));
    r.setValue('u_registeration_status', 'submitted');
    r.setValue('u_registration_number', f.regNo);  r.setValue('u_invoice_number', f.invoice);
    r.setValue('u_colour', f.colour);              r.setValue('u_owner_mobile', f.mobile);
    r.setValue('u_owner_email', f.email);          r.setValue('u_id_type', f.idType);
    r.setValue('u_id_number', f.idNo);             r.setValue('u_street_address', f.street);
    r.setValue('u_city', f.city);  r.setValue('u_state', f.state);  r.setValue('u_pin_code', f.pin);
    r.setValue('u_terms_accepted', true);

    data.newId = r.insert();
    if (!data.newId) { data.error = 'The record could not be created (check ACLs and mandatory fields).'; return; }
    data.ref = pick(r, ['number', 'u_number']) || data.newId.substring(0, 8).toUpperCase();
  }
})();
